-- 0002_topic_schemes_seed (down): removes the seeded scheme versions, their codes (ON DELETE CASCADE) and the topic rows
-- of those versions. GENERATED by upstream/opd/tools/gen_seed.py. Topic rows are lost: export topics.ndjson.gz first.
-- Order: 0003 down first (topic_feed_bodies references topic_schemes; with 0003 applied this fails on that key).
BEGIN;
DELETE FROM topics WHERE scheme_id IN (SELECT id FROM topic_schemes WHERE (scheme_key, version) IN (('aps', 'd8b19c4e'), ('adhoc/digitalisierung', 'c7d99ced'), ('be-directorates', 'b15c8c8c'), ('adhoc/hitze', 'a38d7615'), ('adhoc/ki-schule', '6eabb38c'), ('adhoc/wolf', 'b2ef88fe'), ('bs-themen', 'd758dd54')));
DELETE FROM topic_schemes WHERE (scheme_key, version) IN (('aps', 'd8b19c4e'), ('adhoc/digitalisierung', 'c7d99ced'), ('be-directorates', 'b15c8c8c'), ('adhoc/hitze', 'a38d7615'), ('adhoc/ki-schule', '6eabb38c'), ('adhoc/wolf', 'b2ef88fe'), ('bs-themen', 'd758dd54'));
COMMIT;
